DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ajukan_adopsi` (IN `p_id_adopter` INT, IN `p_id_hewan` INT, OUT `p_pesan` VARCHAR(150))   BEGIN
    DECLARE v_status_hewan VARCHAR(20);
    DECLARE v_staff_default INT;

    -- ambil status hewan saat ini
    SELECT status INTO v_status_hewan
    FROM hewan
    WHERE id_hewan = p_id_hewan;

    IF v_status_hewan IS NULL THEN
        SET p_pesan = 'GAGAL: id_hewan tidak ditemukan.';

    ELSEIF v_status_hewan <> 'Tersedia' THEN
        SET p_pesan = CONCAT('GAGAL: hewan berstatus "', v_status_hewan, '", tidak bisa diajukan adopsi.');

    ELSE
        -- ambil staff pertama yang jabatannya Admin sebagai penanggung jawab wawancara
        SELECT id_staff INTO v_staff_default
        FROM staff_shelter
        WHERE jabatan = 'Admin'
        LIMIT 1;

        VALUES (p_id_adopter, p_id_hewan, v_staff_default, CURDATE(), 'Diajukan', NULL);

        UPDATE hewan SET status = 'Karantina' WHERE id_hewan = p_id_hewan;

        SET p_pesan = 'BERHASIL: sesi adopsi baru berhasil diajukan.';
    END IF;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generate_laporan_populasi` ()   BEGIN
    DECLARE v_id_spesies INT;
    DECLARE v_nama_spesies VARCHAR(50);
    DECLARE v_jumlah INT;
    DECLARE v_status VARCHAR(20);
    DECLARE v_selesai INT DEFAULT 0;

    -- cursor: ambil semua spesies satu per satu
    DECLARE cur_spesies CURSOR FOR
        SELECT id_spesies, nama_spesies FROM spesies;

    -- handler: kalau cursor sudah habis, set v_selesai = 1
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_selesai = 1;

    -- kosongkan laporan lama sebelum generate ulang
    TRUNCATE TABLE laporan_populasi_spesies;

    OPEN cur_spesies;

    baca_loop: LOOP
        FETCH cur_spesies INTO v_id_spesies, v_nama_spesies;

        IF v_selesai = 1 THEN
            LEAVE baca_loop;
        END IF;

        SELECT COUNT(*) INTO v_jumlah
        FROM hewan
        WHERE id_spesies = v_id_spesies;

        IF v_jumlah = 0 THEN
            SET v_status = 'Kosong';
        ELSEIF v_jumlah <= 2 THEN
            SET v_status = 'Sedikit';
        ELSEIF v_jumlah <= 5 THEN
            SET v_status = 'Sedang';
        ELSE
            SET v_status = 'Banyak';
        END IF;

        VALUES (v_nama_spesies, v_jumlah, v_status);

    END LOOP;

    CLOSE cur_spesies;
END$$

--
-- Functions
--
CREATE DEFINER=`root`@`localhost` FUNCTION `fn_kategori_umur_hewan` (`p_umur_bulan` INT, `p_kategori` VARCHAR(20)) RETURNS VARCHAR(20) CHARSET utf8mb4 COLLATE utf8mb4_general_ci DETERMINISTIC BEGIN
    DECLARE label VARCHAR(20);

    IF p_kategori = 'Mamalia' THEN
        IF p_umur_bulan < 6 THEN
            SET label = 'Anak';
        ELSEIF p_umur_bulan BETWEEN 6 AND 24 THEN
            SET label = 'Dewasa';
        ELSE
            SET label = 'Senior';
        END IF;
    ELSE
        IF p_umur_bulan < 12 THEN
            SET label = 'Anak';
        ELSEIF p_umur_bulan BETWEEN 12 AND 36 THEN
            SET label = 'Dewasa';
        ELSE
            SET label = 'Senior';
        END IF;
    END IF;

    RETURN label;
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_total_donasi_uang` () RETURNS DECIMAL(12,2) DETERMINISTIC READS SQL DATA BEGIN
    DECLARE total_uang DECIMAL(12,2);
    SELECT IFNULL(SUM(jumlah_nominal), 0) INTO total_uang
    FROM donasi
    WHERE jenis_donasi = 'Uang';
    RETURN total_uang;
END$$

